// Merges data/about-*.json (per-book notes) into app/about.js, keyed by book path.
const fs = require("fs");
const path = require("path");

const dir = path.join(__dirname, "..", "data");
const out = {};
for (const f of fs.readdirSync(dir).filter((n) => /^about-.*\.json$/.test(n))) {
  for (const e of JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"))) {
    const { path: p, ...rest } = e;
    if (p) out[p] = rest;
  }
}
fs.writeFileSync(
  path.join(__dirname, "..", "app", "about.js"),
  "// GENERATED by scripts/build-about.js from data/about-*.json. Do not hand-edit.\n" +
    "window.ABOUT = " + JSON.stringify(out, null, 1) + ";\n"
);
console.log("notes for", Object.keys(out).length, "books");
